export const DISEASE_DETAILS_LOCALE: Record<string, Record<string, Record<string, string>>> = {"Early Blight": {"symptoms": {"en": "Concentric dark brown to black spots with yellow halos on lower older leaves.", "hi": "निचली पुरानी पत्तियों पर पीले घेरे के साथ संकेंद्री भूरे से काले धब्बे।", "kn": "ಕೆಳಗಿನ ಹಳೆಯ ಎಲೆಗಳ ಮೇಲೆ ಹಳದಿ ವಲಯದೊಂದಿಗೆ ಕಂದು ಮತ್ತು ಕಪ್ಪು ಚುಕ್ಕೆಗಳು ಬರುತ್ತವೆ.", "te": "దిగువ పాత ఆకులపై పసుపు వలయాలతో ముదురు గోధుమ మరియు నలుపు మచ్చలు ఏర్పడతాయి.", "ta": "கீழ் பழைய இலைகளில் மஞ்சள் வளையத்துடன் அடர் பழுப்பு முதல் கருப்பு புள்ளிகள் தோன்றும்.", "ml": "താഴത്തെ പഴയ ഇലകളിൽ മഞ്ഞ വലയത്തോടെയുള്ള തവിട്ട്, കറുപ്പ് പുള്ളികൾ ഉണ്ടാകുന്നു.", "mr": "खालच्या जुन्या पानांवर पिवळ्या कड्यांसह गडद तपकिरी ते काळे ठिपके पडतात.", "gu": "નીચલા જૂના પાંદડા પર પીળા કુંડાળા સાથે ઘેરા બદામી થી કાળા ટપકાં દેખાય છે."}, "causes": {"en": "Alternaria solani fungal infection, highly favored by warm, humid weather and heavy rain/dew.", "hi": "अल्टरनेरिया सोलेनी फंगल संक्रमण, गर्म और आर्द्र मौसम और भारी ओस से बढ़ता है।", "kn": "ಆಲ್ಟರ್ನೇರಿಯಾ ಸೊಲಾನಿ ಶಿಲೀಂಧ್ರ ಸೋಂಕು, ಬಿಸಿಲು ಮತ್ತು ಆದ್ರ್ರ ವಾತಾವರಣದಿಂದ ಹರಡುತ್ತದೆ.", "te": "ఆల్టర్నేరియా సొలానీ ఫంగల్ ఇన్ఫెక్షన్, వెచ్చని మరియు తేమతో కూడిన వాతావరణం వల్ల పెరుగుతుంది.", "ta": "ஆல்டர்னேரியா சொலானி பூஞ்சை தொற்று, வெப்பமான ஈரப்பதமான வானிலையால் அதிகரிக்கிறது.", "ml": "ആൾട്ടർനേറിയ സൊലാനി ഫംഗസ് ബാധ, ചൂടും ഈർപ്പവുമുള്ള കാലാവസ്ഥയിൽ വർദ്ധിക്കുന്നു.", "mr": "अल्टरनेरिया सोलाने बुरशीजन्य संसर्ग, उष्ण व दमट हवामानामुळे वेगाने पसरतो.", "gu": "અલ્ટરનેરિયા સોલાની ફૂગનો ચેપ, ગરમ અને ભેજવાળા હવામાનમાં ઝડપથી ફેલાય છે."}, "treatment": {"en": "Spray Mancozeb 75 WP @ 2.5g/L or Copper Oxychloride 50 WP @ 3g/L of water at first symptom.", "hi": "लक्षण दिखने पर मैंकोजेब 75 WP (2.5 ग्राम/लीटर) या कॉपर ऑक्सीक्लोराइड (3 ग्राम/लीटर) का छिड़काव करें।", "kn": "ರೋಗದ ಲಕ್ಷಣ ಕಂಡ ತಕ್ಷಣ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP (೨.೫ ಗ್ರಾಂ/ಲೀ) ಅಥವಾ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ (೩ ಗ್ರಾಂ/ಲೀ) ಸಿಂಪಡಿಸಿ.", "te": "లక్షణాలు కనిపించగానే మాంకోజెబ్ 75 WP (2.5 గ్రా/లీ) లేదా కాపర్ ఆక్సిక్లోరైడ్ (3 గ్రా/లీ) పిచికారీ చేయండి.", "ta": "அறிகுறிகள் கண்டவுடன் மேன்கோசெப் 75 WP (2.5 கிராம்/லி) அல்லது காப்பர் ஆக்சிகுளோரைடு தெளிக்கவும்.", "ml": "രോഗലക്ഷണം കണ്ടാലുടൻ മാങ്കോസെബ് 75 WP (2.5 ഗ്രാം/ലി) അല്ലെങ്കിൽ കോപ്പർ ഓക്സിക്ലോറൈഡ് തളിക്കുക.", "mr": "लक्षणे दिसताच मँकोझेब 75 WP (२.५ ग्रॅम/ली) किंवा कॉपर ऑक्सिक्लोराईड (३ ग्रॅम/ली) फवारावे.", "gu": "લક્ષણો દેખાય ત્યારે મેંકોઝેબ 75 WP (2.5 ગ્રામ/લીટર) અથવા કોપર ઓક્સીક્લોરાઇડનો છંટકાવ કરો."}, "prevention": {"en": "Use disease-free certified seeds, adopt crop rotation with non-solanaceous crops, and maintain spacing.", "hi": "प्रमाणित बीज का उपयोग करें, गैर-सोलनेसी फसलों के साथ फसल चक्र अपनाएं और उचित दूरी बनाएं।", "kn": "ರೋಗರಹಿತ ಪ್ರಮಾಣೀಕೃತ ಬೀಜ ಬಳಸಿ, ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡಿ ಮತ್ತು ಸರಿಯಾದ ಅಂತರ ಕಾಯ್ದುಕೊಳ್ಳಿ.", "te": "ధృవీకరించబడిన విత్తనాలను ఉపయోగించండి, పంట మార్పిడి పాటించండి మరియు తగిన అంతరం నిర్వహించండి.", "ta": "சான்றளிக்கப்பட்ட விதைகளைப் பயன்படுத்தவும், பயிர் சுழற்சியைப் பின்பற்றவும், இடைவெளியைப் பராமரிக்கவும்.", "ml": "സാക്ഷ്യപ്പെടുത്തിയ വിത്തുകൾ ഉപയോഗിക്കുക, വിള പരിക്രമണം നടത്തുക, ശരിയായ അകലം പാലിക്കുക.", "mr": "प्रमाणित बियाणे वापरा, पीक पालट करा आणि पिकांमध्ये योग्य अंतर ठेवा.", "gu": "પ્રમાણિત બિયારણ વાપરો, પાક ફેરબદલી કરો અને યોગ્ય અંતર જાળવો."}, "precautions": {"en": "Destroy infected plant debris after harvest and avoid overhead sprinkler irrigation.", "hi": "कटाई के बाद संक्रमित अवशेषों को नष्ट करें और ऊपर से सिंचाई (स्प्रिंकलर) करने से बचें।", "kn": "ಕೊಯ್ಲಿನ ನಂತರ ಸೋಂಕಿತ ಎಲೆಗಳನ್ನು ನಾಶಪಡಿಸಿ ಮತ್ತು ಮೇಲಿಂದ ನೀರು ಸಿಂಪಡಿಸುವುದನ್ನು ತಪ್ಪಿಸಿ.", "te": "కోత తర్వాత ప్రభావిత వ్యర్థాలను నాశనం చేయండి మరియు పైనుండి నీటిపారుదల నివారించండి.", "ta": "அறுவடைக்குப் பின் பாதிக்கப்பட்ட கழிவுகளை அழிக்கவும், தெளிப்பு நீர்ப்பாசனத்தைத் தவிர்க்கவும்.", "ml": "വിളവെടുപ്പിനുശേഷം രോഗബാധിതമായ അവശിഷ്ടങ്ങൾ നശിപ്പിക്കുക, തളിക്കൽ നന ഒഴിവാക്കുക.", "mr": "काढणीनंतर बाधित पिकांचे उर्वरित भाग नष्ट करा आणि वरून पाणी देणे टाळा.", "gu": "લણણી પછી અસરગ્રસ્ત અવશેષોનો નાશ કરો અને ઉપરથી પિયત આપવાનું ટાળો."}}, "Red Rot": {"symptoms": {"en": "Reddening of internal stalk tissues with white transverse patches, drying of upper leaves.", "hi": "तने के आंतरिक ऊतकों का लाल होना, सफेद पट्टियाँ बनना और ऊपरी पत्तियों का सूखना।", "kn": "ಕಬ್ಬಿನ ಗಂಟಿನ ಒಳಭಾಗ ಕೆಂಪು ಬಣ್ಣಕ್ಕೆ ತಿರುಗಿ ಬಿಳಿ ಚುಕ್ಕೆಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ, ಮೇಲಿನ ಎಲೆಗಳು ಒಣಗುತ್ತವೆ.", "te": "కంబం లోపలి కణజాలం ఎర్రబడటం, తెల్లటి అడ్డ మచ్చలు ఏర్పడటం మరియు పై ఆకులు ఎండిపోవడం.", "ta": "தண்டின் உட்பகுதி சிவத்தல், வெள்ளை நிறக் கோடுகள் தோன்றுதல் மற்றும் மேல் இலைகள் காய்ந்துபோதல்.", "ml": "തണ്ടിന്റെ ഉൾഭാഗം ചുവക്കുകയും വെളുത്ത പാടുകൾ വരികയും മുകളിലത്തെ ഇലകൾ ഉണങ്ങുകയും ചെയ്യുന്നു.", "mr": "कांडाचा आतील भाग लाल होणे, पांढरे पट्टे पडणे आणि वरची पाने वाळणे.", "gu": "સાંધાના આંતરિક ભાગો લાલ થવા, સફેદ પટ્ટાઓ બનવા અને ઉપરના પાંદડા સુકાવા."}, "causes": {"en": "Colletotrichum falcatum fungal pathogen spread through infected setts and waterlogging.", "hi": "कोलेटोट्राइकम फाल्केटम फंगस, जो संक्रमित बीजों और जलजमाव से फैलता है।", "kn": "ಕೊಲೆಟೊಟ್ರಿಕಮ್ ಫಾಲ್ಕಾಟಮ್ ಶಿಲೀಂಧ್ರ, ಸೋಂಕಿತ ಕಬ್ಬಿನ ತುಂಡುಗಳು ಮತ್ತು ನೀರು ನಿಲ್ಲುವುದರಿಂದ ಹರಡುತ್ತದೆ.", "te": "కొలెటోట్రైకమ్ ఫాల్కాటమ్ ఫంగస్, సోకిన పిలకలు మరియు నీరు నిల్వ ఉండటం ద్వారా వ్యాపిస్తుంది.", "ta": "கொலட்டோட்ரைக்கம் ஃபால்கேட்டம் பூஞ்சை, பாதிக்கப்பட்ட கரணைகள் மற்றும் நீர் தேங்குவதால் பரவுகிறது.", "ml": "കൊളറ്റോട്രിക്കം ഫാൽക്കാറ്റം ഫംഗസ്, രോഗമുള്ള തണ്ടുകളിലൂടെയും വെള്ളക്കെട്ടിലൂടെയും പടരുന്നു.", "mr": "कोलेटोट्रायकम फाल्काटम बुरशी, बाधित कांडांमुळे आणि साचलेल्या पाण्यामुळे पसरते.", "gu": "કોલેટોટ્રાઇકમ ફાલ્કેટમ ફૂગ, જે ચેપગ્રસ્ત સાંઠાઓ અને ભરાયેલા પાણી દ્વારા ફેલાય છે."}, "treatment": {"en": "Rogue out infected clumps immediately. Treat seed setts with Carbendazim 50 WP @ 2g/L.", "hi": "संक्रमित पौधों को तुरंत उखाड़कर नष्ट करें। बीजों को कार्बेन्डाजिम 50 WP (2 ग्राम/लीटर) से उपचारित करें।", "kn": "ಸೋಂಕಿತ ಗಿಡಗಳನ್ನು ತಕ್ಷಣ ಕಿತ್ತು ನಾಶಪಡಿಸಿ. ಕಬ್ಬಿನ ತುಂಡುಗಳನ್ನು ಕಾರ್ಬೆಂಡಾಜಿಮ್ (೨ ಗ್ರಾಂ/ಲೀ) ನಿಂದ ಸಂಸ್ಕರಿಸಿ.", "te": "సోకిన మొక్కలను వెంటనే పీకి నాశనం చేయండి. విత్తన పిలకలను కార్బండజిమ్ (2 గ్రా/లీ) తో శుద్ధి చేయండి.", "ta": "பாதிக்கப்பட்ட பயிர்களை以内に பிடுங்கி அழிக்கவும். கரணைகளை கார்பண்டசிம் (2 கிராம்/லி) கொண்டு நேர்த்தி செய்யவும்.", "ml": "രോഗബാധിതമായ ചെടികൾ ഉടനടി പിഴുതുമാറ്റി നശിപ്പിക്കുക. വിത്തുതണ്ടുകൾ കാർബൻഡാസിം കൊണ്ട് ഉപചരിക്കുക.", "mr": "बाधित झाडे ताबडतोब उपटून नष्ट करा. बियाणे कांडांना कार्बेन्डाझिम (२ ग्रॅम/ली) ची प्रक्रिया करा.", "gu": "ચેપગ્રસ્ત છોડને તરત જ ઉખાડી નાખો. વાવણી સાંઠાઓને કાર્બેન્ડાઝિમ (2 ગ્રામ/લીટર) થી પટ આપો."}, "prevention": {"en": "Plant resistant sugarcane varieties (Co 0238, Co 86032) and maintain field drainage.", "hi": "प्रतिरोधी किस्मों (जैसे Co 86032) की बुआई करें और खेत में जल निकासी की उचित व्यवस्था रखें।", "kn": "ರೋಗ ನಿರೋಧಕ ತಳಿಗಳನ್ನು (ಉದಾ: Co 86032) ಬೆಳೆಯಿರಿ ಮತ್ತು ಹೊಲದಲ್ಲಿ ನೀರು ಹರಿದು ಹೋಗುವಂತೆ ನೋಡಿಕೊಳ್ಳಿ.", "te": "నిరోధక రకాలను (ఉదా: Co 86032) నాటండి మరియు పొలంలో నీటి నిష్క్రాసన సదుపాయం కల్పించండి.", "ta": "நோயெதிர்ப்புத் திறன் கொண்ட ரகங்களை (Co 86032) பயிரிடவும், வடிகால் வசதியை ஏற்படுத்தவும்.", "ml": "രോഗപ്രതിരോധശേഷിയുള്ള ഇനങ്ങൾ നടുക, കൃഷിയിടത്തിൽ വെള്ളക്കെട്ട് ഒഴിവാക്കുക.", "mr": "रोगप्रतिकारक वाणांची (Co 86032) लागवड करा आणि शेतात पाण्याचा निचरा व्यवस्थित ठेवा.", "gu": "રોગપ્રતિકારક જાતો (Co 86032) ની વાવણી કરો અને ખેતરમાં સારા નિકાલની વ્યવસ્થા રાખો."}, "precautions": {"en": "Avoid taking ratoon crops from infected fields and do not use setts from diseased plots.", "hi": "संक्रमित खेतों से पेड़ी फसल न लें और रोगग्रस्त खेतों के बीजों का उपयोग न करें।", "kn": "ಸೋಂಕಿತ ಹೊಲಗಳಿಂದ ಮರುಬೆಳೆ (ಕೂಳೆ) ತೆೆಗೆದುಕೊಳ್ಳಬೇಡಿ ಮತ್ತು ರೋಗಪೀಡಿತ ಬೀಜ ಬಳಸಬೇಡಿ.", "te": "సోకిన పొలాల నుండి కార్శి పంట తీసుకోకండి మరియు రోగగ్రస్థ విత్తనాలను ఉపయోగించవద్దు.", "ta": "பாதிக்கப்பட்ட நிலங்களிலிருந்து மறுதாம்பு பயிர் செய்வதைத் தவிர்க்கவும், நோய்வாய்ப்பட்ட கரணைகளைப் பயன்படுத்த வேண்டாம்.", "ml": "രോഗബാധിത പ്രദേശങ്ങളിൽ നിന്ന് മറുവിള എടുക്കരുത്, രോഗമുള്ള തണ്ടുകൾ നടാനെടുക്കരുത്.", "mr": "बाधित शेतातून खोडवा पीक घेऊ नका आणि आजारी शेतातील बियाणे वापरू नका.", "gu": "ચેપગ્રસ્ત ખેતરોમાંથી પોષણ પાક ન લો અને રોગગ્રસ્ત ખેતરના સાંઠા વાપરશો નહીં."}}, "Yellow Rust (Stripe Rust)": {"symptoms": {"en": "Bright yellow pustules arranged in linear stripes on wheat leaf blades.", "hi": "गेहूं की पत्तियों पर लंबी धारियों में चमकीले पीले रंग के फफोले (पस्ट्यूल्स)।", "kn": "ಗೋಧಿ ಎಲೆಗಳ ಮೇಲೆ ಸಾಲಾಗಿ ಹಳದಿ ಬಣ್ಣದ ಗಂಟುಗಳು/ಚುಕ್ಕೆಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.", "te": "గోధుమ ఆకులపై నిలువు వరుసలలో ప్రకాశవంతమైన పసుపు మచ్చలు/పొక్కులు.", "ta": "கோதுமை இலைகளில் நீண்ட வரிகளாக பிரகாசமான மஞ்சள் நிற கொப்புளங்கள் தோன்றும்.", "ml": "ഗോതമ്പ് ഇലകളിൽ നീളമുള്ള നിരയായി മഞ്ഞ നിറത്തിലുള്ള പുള്ളികൾ പ്രത്യക്ഷപ്പെടുന്നു.", "mr": "गव्हाच्या पानांवर उभ्या ओळींमध्ये पिवळ्या रंगाचे फोड पडतात.", "gu": "ઘઉંના પાંદડા પર લાંબી લીટીઓમાં તેજસ્વી પીળા ફોલ્લા દેખાય છે."}, "causes": {"en": "Puccinia striiformis fungal spores spread rapidly in cool (10-15°C) moist conditions.", "hi": "पुसीनिया स्ट्रिफोर्मिस फंगस, जो ठंडे और नमी वाले मौसम (10-15°C) में तेजी से फैलता है।", "kn": "ಪುಸ್ಸಿನಿಯಾ ಸ್ಟ್ರೈಫಾರ್ಮಿಸ್ ಶಿಲೀಂಧ್ರದ ಬೀಜಕಗಳು ತಂಪಾದ ಮತ್ತು ತೇವದ ಹವಾಮಾನದಲ್ಲಿ ಪಸರಿಸುತ್ತವೆ.", "te": "పుస్సీనియా స్ట్రైఫార్మిస్ ఫంగస్, చల్లని (10-15°C) మరియు తేమతో కూడిన వాతావరణంలో వేగంగా వ్యాపిస్తుంది.", "ta": "புச்சினியா ஸ்ட்ரைஃபார்மிஸ் பூஞ்சை, குளிர்ந்த ஈரப்பதமான வானிலையில் வேகமாக பரவுகிறது.", "ml": "പക്സീനിയ സ്ട്രൈഫോർമിസ് ഫംഗസ്, തണുപ്പുള്ള ഈർപ്പമുള്ള അന്തരീക്ഷത്തിൽ വേഗത്തിൽ പടരുന്നു.", "mr": "पुक्सिनिया स्ट्रायफॉर्मिस बुरशी, थंड (१०-१५°C) व ओलसर हवामानात वेगाने पसरते.", "gu": "પુસીનિયા સ્ટ્રાઇફોર્મિસ ફૂગના બીજાણુઓ, જે ઠંડા અને ભેજવાળા હવામાનમાં ઝડપથી ફેલાય છે."}, "treatment": {"en": "Spray Propiconazole 25 EC @ 1ml/L or Tebuconazole 259 EC @ 1ml/L immediately.", "hi": "प्रोपीकोनाज़ोल 25 EC (1 मिली/लीटर) या टेबुकोनाज़ोल का तुरंत छिड़काव करें।", "kn": "ತಕ್ಷಣವೇ ಪ್ರೊಪಿಕೊನಾಝೋಲ್ 25 EC (೧ ಮಿಲಿ/ಲೀ) ಅಥವಾ ಟೆಬುಕೊನಾಝೋಲ್ ಸಿಂಪಡಿಸಿ.", "te": "వెంటనే ప్రొపికోనాజోల్ 25 EC (1 మిలీ/లీ) లేదా టెబుకోనాజోల్ పిచికారీ చేయండి.", "ta": "உடனடியாக புரோபிகோனசோல் 25 EC (1 மி.லி/லி) தெளிக்கவும்.", "ml": "ഉടനടി പ്രൊപ്പിക്കൊണാസോൾ 25 EC (1 മില്ലി/ലി) തളിക്കുക.", "mr": "तात्काळ प्रोपिकोनाझोल 25 EC (१ मिली/ली) किंवा टेबुकोनाझोल फवारावे.", "gu": "તરત જ પ્રોપિકોનાઝોલ 25 EC (1 મિલી/લીટર) અથવા ટેબુકોનાઝોલનો છંટકાવ કરો."}, "prevention": {"en": "Sow rust-resistant varieties (HD 3086, DBW 187) and avoid late sowing.", "hi": "रतुआ-रोधी किस्मों (HD 3086, DBW 187) की बुआई करें और देर से बुआई से बचें।", "kn": "ರೋಗ ನಿರೋಧಕ ತಳಿಗಳನ್ನು (HD 3086, DBW 187) ಬಿತ್ತನೆ ಮಾಡಿ ಮತ್ತು ತಡವಾಗಿ ಬಿತ್ತುವುದನ್ನು ತಪ್ಪಿಸಿ.", "te": "తెగులు నిరోధక రకాలను (HD 3086, DBW 187) విత్తండి మరియు ఆలస్యపు విత్తనాన్ని నివారించండి.", "ta": "துரு நோயெதிர்ப்பு ரகங்களை (HD 3086) விதைக்கவும், தாமதமான விதைப்பைத் தவிர்க்கவும்.", "ml": "രോഗപ്രതിരോധശേഷിയുള്ള ഇനങ്ങൾ വിതയ്ക്കുക, വൈകിയുള്ള വിത ഒഴിവാക്കുക.", "mr": "तांबेरा-प्रतिबंधक वाणांची (HD 3086) पेरणी करा आणि उशिरा पेरणी करणे टाळा.", "gu": "ગેરુ-પ્રતિકારક જાતો (HD 3086) ની વાવણી કરો અને મોડી વાવણી ટાળો."}, "precautions": {"en": "Monitor fields weekly during December-February and avoid excessive nitrogen fertilizer.", "hi": "दिसंबर-फरवरी में साप्ताहिक निगरानी करें और अत्यधिक नाइट्रोजन उर्वरक से बचें।", "kn": "ಡಿಸೆಂಬರ್-ಫೆಬ್ರವರಿ ಅವಧಿಯಲ್ಲಿ ಪ್ರತಿ ವಾರ ಹೊಲ ಪರೀಕ್ಷಿಸಿ ಮತ್ತು ಅತಿಯಾದ ಸಾರಜನಕ ಬಳಸಬೇಡಿ.", "te": "డిసెంబర్-ఫిబ్రవరి మధ్య వారానికొకసారి పొలాన్ని పర్యవేక్షించండి మరియు అధిక నత్రజని వాడవద్దు.", "ta": "டிசம்பர்-பிப்ரவரி மாதங்களில் வாரந்தோறும் வயலைக் கண்காணிக்கவும், அதிக நைட்ரஜனைத் தவிர்க்கவும்.", "ml": "ഡിസംബർ-ഫെബ്രുവരി മാസങ്ങളിൽ ആഴ്ചതോറും പരിശോധിക്കുക, അമിത നൈട്രജൻ ഒഴിവാക്കുക.", "mr": "डिसेंबर-फेब्रुवारी दरम्यान दर आठवड्याला पाहणी करा आणि जास्त नायट्रोजन वापरणे टाळा.", "gu": "ડિસેમ્બર-ફેબ્રુઆરી દરમિયાન દર અઠવાડિયે ખેતરની ચકાસણી કરો અને વધુ પડતા નાઇટ્રોજનથી બચો."}}, "Rice Blast": {"symptoms": {"en": "Spindle-shaped lesions with greyish centers and dark margins on rice leaves and panicles.", "hi": "धान की पत्तियों और बालियों पर धूसर केंद्र और काले किनारों वाले तकुवा-आकार (स्पिंडल) के धब्बे।", "kn": "ಎಲೆಗಳ ಮೇಲೆ ಮಧ್ಯದಲ್ಲಿ ಬೂದು ಬಣ್ಣ ಮತ್ತು ಕಂಚಿನ ಅಂಚುಗಳುಳ್ಳ ಆಕಾರದ ಬೆಂಕಿ ಚುಕ್ಕೆಗಳು ಕಾಣಿಸುತ್ತವೆ.", "te": "వరి ఆకులపై బూడిద రంగు కేంద్రం మరియు ముదురు అంచులతో కదురు ఆకారపు మచ్చలు.", "ta": "நெல் இலைகளில் சாம்பல் நிற மையம் கொண்ட சுழல் வடிவப் புள்ளிகள் தோன்றும்.", "ml": "ഇലകളിൽ ചാരനിറമുള്ള മധ്യഭാഗത്തോടുകൂടിയ തയ്യൽ ആകൃതിയിലുള്ള പാടുകൾ.", "mr": "पानांवर राखाडी केंद्र आणि काळ्या कडा असलेले लांबट करप्याचे ठिपके.", "gu": "ડાંગરના પાંદડા પર રાખોડી કેન્દ્ર અને કાળી ધાર વાળા ત્રાક આકારના ટપકાં."}, "causes": {"en": "Magnaporthe oryzae fungus airborne spores favoured by high relative humidity (>90%).", "hi": "मैग्नापोर्थे ओराइज़ी फंगस, जो 90% से अधिक आर्द्रता और बादलों वाले मौसम में फैलता है।", "kn": "ಮ್ಯಾಗ್ನಾಪೋರ್ಥೆ ಒರೈಝೆ ಶಿಲೀಂಧ್ರ, ಹೆಚ್ಚಿನ ತೇವಾಂಶ ಮತ್ತು ಮೋಡ ಮುಸುಕಿದ ವಾತಾವರಣದಲ್ಲಿ ಹರಡುತ್ತದೆ.", "te": "మాగ్నాపోర్తే ఒరైజే ఫంగస్, అధిక సాపేక్ష తేమ (>90%) ఉన్నప్పుడు వేగంగా వ్యాపిస్తుంది.", "ta": "மேக்னபோர்த்தே ஒரைசே பூஞ்சை, அதிக ஈரப்பதமான வானிலையில் பரவுகிறது.", "ml": "മാഗ്നാപോർത്തെ ഒറൈസെ ഫംഗസ്, ഉയർന്ന ഈർപ്പമുള്ള അന്തരീക്ഷത്തിൽ പടരുന്നു.", "mr": "मॅग्नापोर्थे ओरायझे बुरशी, ९०% पेक्षा जास्त दमट हवेत वेगाने पसरते.", "gu": "મેગ્નાપોર્થે ઓરાઇઝી ફૂગ, જે વધુ ભેજવાળા હવામાનમાં ઝડપથી ફેલાય છે."}, "treatment": {"en": "Spray Tricyclazole 75 WP @ 0.6g/L or Isoprothiolane 40 EC @ 1.5ml/L at disease initiation.", "hi": "रोग शुरू होते ही ट्राइसाइक्लाज़ोल 75 WP (0.6 ग्राम/लीटर) या आइसोप्रोथिओलेन का छिड़काव करें।", "kn": "ರೋಗ ಪ್ರಾರಂಭವಾಗುತ್ತಿದ್ದಂತೆ ಟ್ರೈಸೈಕ್ಲಾಝೋಲ್ 75 WP (೦.೬ ಗ್ರಾಂ/ಲೀ) ಸಿಂಪಡಿಸಿ.", "te": "తెగులు ప్రారంభంలోనే ట్రైసైక్లాజోల్ 75 WP (0.6 గ్రా/లీ) పిచికారీ చేయండి.", "ta": "நோய் தொடங்கும் போது டிரைசைக்ளசோல் 75 WP (0.6 கிராம்/லி) தெளிக்கவும்.", "ml": "രോഗം കണ്ടുതുടങ്ങുമ്പോൾ ട്രൈസൈക്ലാസോൾ 75 WP (0.6 ഗ്രാം/ലി) തളിക്കുക.", "mr": "रोग सुरू होताच ट्रायसायक्लाझोल 75 WP (०.६ ग्रॅम/ली) फवारावे.", "gu": "રોગની શરૂઆતમાં ટ્રાઇસાઇકલાઝોલ 75 WP (0.6 ગ્રામ/લીટર) નો છંટકાવ કરો."}, "prevention": {"en": "Avoid excessive nitrogen application and use blast-resistant cultivars.", "hi": "अत्यधिक नाइट्रोजन का प्रयोग न करें और रोग-रोधी किस्मों की रोपाई करें।", "kn": "ಅತಿಯಾದ ಸಾರಜನಕ ಬಳಸಬೇಡಿ ಮತ್ತು ಬೆಂಕಿ ರೋಗ ನಿರೋಧಕ ತಳಿಗಳನ್ನು ಬೆಳೆಯಿರಿ.", "te": "అధిక నత్రజని వాడకాన్ని నివారించండి మరియు నిరోధక రకాలను ఉపయోగించండి.", "ta": "அதிக நைட்ரஜன் உரங்களைத் தவிர்க்கவும், பிளாஸ்ட் எதிர்ப்பு ரகங்களைப் பயன்படுத்தவும்.", "ml": "അമിത നൈട്രജൻ പ്രയോഗം ഒഴിവാക്കുക, പ്രതിരോധശേഷിയുള്ള ഇനങ്ങൾ ഉപയോഗിക്കുക.", "mr": "अतिरिक्त नायट्रोजन वापरणे टाळा आणि करपा-प्रतिबंधक वाण वापरा.", "gu": "વધુ પડતા નાઇટ્રોજનનો ઉપયોગ ટાળો અને રોગપ્રતિકારક જાતો વાવો."}, "precautions": {"en": "Maintain 2-5 cm standing water in paddy fields and treat seeds with Pseudomonas fluorescens.", "hi": "खेत में 2-5 सेमी पानी बनाए रखें और स्यूडोमोनास फ्लोरेसेंस से बीज उपचार करें।", "kn": "ಗದ್ದೆಯಲ್ಲಿ ೨-೫ ಸೆಂ.ಮೀ ನೀರು ನಿಲ್ಲಿಸಿ ಮತ್ತು ಬೀಜೋಪಚಾರ ಮಾಡಿ ಬಿತ್ತನೆ ಮಾಡಿ.", "te": "వరి పొలాల్లో 2-5 సెం.మీ నీటిని నిర్వహించండి మరియు విత్తన శుద్ధి చేయండి.", "ta": "வயலில் 2-5 செ.மீ நீர் மட்டத்தைப் பராமரிக்கவும், விதை நேர்த்தி செய்யவும்.", "ml": "പാടത്ത് 2-5 സെ.മീ വെള്ളം നിലനിർത്തുക, ജൈവ വിത്തുപചാരം നടത്തുക.", "mr": "शेतात २-५ सेंमी पाणी साचवून ठेवा आणि बियाणे प्रक्रिया करा.", "gu": "ખેતરમાં 2-5 સેમી પાણી જાળવી રાખો અને બિયારણ પટ આપો."}}, "default": {"symptoms": {"en": "Discoloration, spots, or blights on crop leaves and stems.", "hi": "फसल की पत्तियों और तनों पर मलिनकिरण, धब्बे या झुलसा के लक्षण।", "kn": "ಬೆಳೆಯ ಎಲೆಗಳು ಮತ್ತು ಕಾಂಡಗಳ ಮೇಲೆ ಬಣ್ಣ ಬದಲಾವಣೆ ಹಾಗೂ ಚುಕ್ಕೆಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.", "te": "పంట ఆకులు మరియు కాండంపై రంగు మారడం, మచ్చలు లేదా ఎండు లక్షణాలు.", "ta": "பயிர் இலைகள் மற்றும் தண்டுகளில் நிறமாற்றம், புள்ளிகள் அல்லது கருகல் அறிகுறிகள்.", "ml": "വിളകളുടെ ഇലകളിലും തണ്ടുകളിലും നിറംമാറ്റവും പാടുകളും പ്രത്യക്ഷപ്പെടുന്നു.", "mr": "पिकाची पाने व खोडावर रंग बदलणे, ठिपके किंवा करपा येणे.", "gu": "પાકના પાંદડા અને પ્રકાંડ પર વિકૃતિ, ટપકાં અથવા સુકારો."}, "causes": {"en": "Fungal or bacterial pathogen infection favored by high atmospheric humidity.", "hi": "उच्च वायुमंडलीय आर्द्रता के कारण कवक या जीवाणु रोगजनक का संक्रमण।", "kn": "ಹೆಚ್ಚಿನ ತೇವಾಂಶದ ವಾತಾವರಣದಿಂದ ಉಂಟಾಗುವ ಶಿಲೀಂಧ್ರ ಅಥವಾ ಬ್ಯಾಕ್ಟೀರಿಯಾ ಸೋಂಕು.", "te": "అధిక వాతావరణ తేమ వల్ల ఫంగల్ లేదా బాక్టీరియల్ ఇన్ఫెక్షన్ సోకుతుంది.", "ta": "அதிக வளிமண்டல ஈரப்பதத்தால் பூஞ்சை அல்லது பாக்டீரியா தொற்று ஏற்படுகிறது.", "ml": "ഉയർന്ന ഈർപ്പം കാരണം ഫംഗസ് അല്ലെങ്കിൽ ബാക്ടീരിയ ബാധ ഉണ്ടാകുന്നു.", "mr": "हवेतील जास्त दमटपणामुळे बुरशीजन्य किंवा जिवाणूजन्य संसर्ग होतो.", "gu": "હવામાનમાં વધુ ભેજને કારણે ફૂગ અથવા બેક્ટેરિયાનો ચેપ ફેલાય છે."}, "treatment": {"en": "Apply recommended crop-specific treatment, bio-pesticides, or approved fungicides.", "hi": "अनुशंसित फसल-विशिष्ट उपचार, जैविक कीटनाशक या अनुमोदित कवकनाशी लागू करें।", "kn": "ಶಿಫಾರಸು ಮಾಡಿದ ಕೃಷಿ ಔಷಧಗಳು, ಜೈವಿಕ ಕೀಟನಾಶಕಗಳು ಅಥವಾ ಶಿಲೀಂಧ್ರನಾಶಕಗಳನ್ನು ಬಳಸಿ.", "te": "సిఫార్సు చేసిన పంట-నిర్దిష్ట చికిత్స, బయో-పెస్టిసైడ్లు లేదా ఫంగిసైడ్లను వాడండి.", "ta": "பரிந்துரைக்கப்பட்ட பயிர்-சார்ந்த சிகிச்சை, உயிர்-பூச்சிக்கொல்லிகளைப் பயன்படுத்தவும்.", "ml": "ശുപാർശ ചെയ്യുന്ന ജൈവ കീടനാശിനികളോ ഫംഗിസൈഡുകളോ ഉപയോഗിക്കുക.", "mr": "शिफारस केलेले पीक-विशिष्ट उपचार, जैविक कीटकनाशके किंवा बुरशीनाशके वापरा.", "gu": "ભલામણ કરેલ પાક-વિશિષ્ટ ઉપચાર, જૈવિક જંતુનાશકો અથવા ફૂગનાશકો વાપરો."}, "prevention": {"en": "Ensure proper plant spacing, crop rotation, and adequate field drainage.", "hi": "पौधों के बीच उचित दूरी, फसल चक्र और खेत में जल निकासी की व्यवस्था सुनिश्चित करें।", "kn": "ಗಿಡಗಳ ನಡುವೆ ಸರಿಯಾದ ಅಂತರ, ಬೆಳೆ ಪರಿವರ್ತನೆ ಮತ್ತು ನೀರಿನ ಹರಿವು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.", "te": "సరైన మొక్కల అంతరం, పంట మార్పిడి మరియు పొలంలో నీటి నిష్క్రాసన నిర్ధారించుకోండి.", "ta": "சரியான பயிர் இடைவெளி, பயிர் சுழற்சி மற்றும் நீர் வடிகால் வசதியை உறுதி செய்யவும்.", "ml": "ചെടികൾ തമ്മിൽ അകലം പാലിക്കുക, കൃഷി മാറ്റം വരുത്തുക, വെള്ളക്കെട്ട് ഒഴിവാക്കുക.", "mr": "रोपांमध्ये योग्य अंतर ठेवा, पीक पालट करा आणि पाण्याचा निचरा व्यवस्थित करा.", "gu": "છોડ વચ્ચે યોગ્ય અંતર, પાક ફેરબદલી અને ખેતરમાં સારા નિકાલની વ્યવસ્થા કરો."}, "precautions": {"en": "Wear protective gear during spraying and safely destroy severely infected leaf debris.", "hi": "छिड़काव के दौरान सुरक्षात्मक गियर पहनें और संक्रमित पत्तियों को सुरक्षित रूप से नष्ट करें।", "kn": "ಔಷಧಿ ಸಿಂಪಡಿಸುವಾಗ ರಕ್ಷಣಾತ್ಮಕ ಕವಚ ಧರಿಸಿ ಮತ್ತು ಸೋಂಕಿತ ಎಲೆಗಳನ್ನು ನಾಶಪಡಿಸಿ.", "te": "పిచಿಕారీ చేసేటప్పుడు రక్షణ దుస్తులు ధరించండి మరియు సోకిన ఆకులను నాశనం చేయండి.", "ta": "தெளிக்கும் போது பாதுகாப்பு உடைகளை அணியுங்கள், பாதிக்கப்பட்ட இலைகளை அழிக்கவும்.", "ml": "മരുന്ന് തളിക്കുമ്പോൾ സുരക്ഷാ വസ്ത്രങ്ങൾ ധരിക്കുക, രോഗമുള്ള ഇലകൾ നശിപ്പിക്കുക.", "mr": "फवारणी करताना संरक्षक गणवेश वापरा आणि बाधित पाने सुरक्षितपणे नष्ट करा.", "gu": "છંટકાવ વખતે રક્ષણાત્મક વસ્ત્રો પહેરો અને ચેપગ્રસ્ત અવશેષોનો સુરક્ષિત નાશ કરો."}}};

export const RECOMMENDED_ACTIONS_LOCALE: Record<string, Record<string, string[]>> = {"Early Blight": {"en": ["Inspect surrounding Tomato plants for early symptoms of Early Blight.", "Apply Mancozeb 75 WP @ 2.5g per liter of water as a preventive spray.", "Avoid overhead irrigation to keep leaf surfaces dry."], "hi": ["अगेती झुलसा के शुरुआती लक्षणों के लिए आसपास के टमाटर के पौधों की जांच करें।", "निवारक स्प्रे के रूप में मैंकोजेब 75 WP (2.5 ग्राम प्रति लीटर पानी) लागू करें।", "पत्तियों की सतह को सूखा रखने के लिए ऊपर से सिंचाई करने से बचें।"], "kn": ["ಅಗಾಧ ಕೊಳೆ ರೋಗದ ಆರಂಭಿಕ ಲಕ್ಷಣಗಳಿಗಾಗಿ ಸುತ್ತಮುತ್ತಲಿನ ಟೊಮೆಟೊ ಗಿಡಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ.", "ಮುನ್ನೆಚ್ಚರಿಕೆಯಾಗಿ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP (೨.೫ ಗ್ರಾಂ/ಲೀಟರ್‌ ನೀರಿಗೆ) ಸಿಂಪಡಿಸಿ.", "ಎಲೆಗಳು ಒಣಗಿರಲು ಮೇಲಿಂದ ನೀರು ಸಿಂಪಡಿಸುವುದನ್ನು ತಪ್ಪಿಸಿ."], "te": ["తొలి ఆకు ఎండు తెగులు ప్రారంభ లక్షణాల కోసం చుట్టుపక్కల టమాటా మొక్కలను తనిఖీ చేయండి.", "ముందస్తు నివారణగా లీటరు నీటికి మాంకోజెబ్ 75 WP 2.5 గ్రాముల చొప్పున పిచికారీ చేయండి.", "ఆకుల ఉపరితలాలు పొడిగా ఉంచడానికి పైనుండి నీటిపారుదల నివారించండి."], "ta": ["முன் கருகல் நோயின் ஆரம்ப அறிகுறிகளுக்கு சுற்றியுள்ள தக்காளி பயிர்களை சோதிக்கவும்.", "முன்னெச்சரிக்கையாக லீட்டருக்கு 2.5 கிராம் மேன்கோசெப் 75 WP தெளிக்கவும்.", "இலைகள் உலர்ந்திருக்க தெளிப்பு நீர்ப்பாசனத்தைத் தவிர்க்கவும்."], "ml": ["മുൻകാല കരിഞ്ചെടി രോഗലക്ഷണങ്ങൾക്കായി ചുറ്റുമുള്ള തക്കാളി ചെടികൾ പരിശോധിക്കുക.", "മുൻകരുതലായി മാങ്കോസെബ് 75 WP (2.5 ഗ്രാം/ലിറ്റർ വെള്ളത്തിൽ) തളിക്കുക.", "ഇലകൾ വരണ്ടുനിൽക്കാൻ തളിക്കൽ നന ഒഴിവാക്കുക."], "mr": ["अर्ली ब्लाइटच्या सुरुवातीच्या लक्षणांसाठी सभोवतालच्या टोमॅटो झाडांची पाहणी करा.", "प्रतिबंधात्मक उपाय म्हणून मँकोझेब 75 WP (२.५ ग्रॅम प्रति लिटर पाणी) फवारावे.", "पाने कोरडी ठेवण्यासाठी वरून पाणी देणे टाळा."], "gu": ["અગાઉના સુકારાના શરૂઆતી લક્ષણો માટે આસપાસના ટામેટાના છોડની તપાસ કરો.", "રક્ષણાત્મક છંટકાવ તરીકે મેંકોઝેબ 75 WP (2.5 ગ્રામ પ્રતિ લીટર પાણી) છાંટો.", "પાંદડા સુકા રાખવા માટે ઉપરથી પિયત આપવાનું ટાળો."]}, "Red Rot": {"en": ["Remove and safely burn infected sugarcane clumps to prevent pathogen spread.", "Drench surrounding soil with Carbendazim 50 WP @ 2g per liter of water.", "Ensure field drainage to eliminate standing water in channels."], "hi": ["रोगजनक के प्रसार को रोकने के लिए संक्रमित गन्ने के पौधों को उखाड़कर जला दें।", "आसपास की मिट्टी में कार्बेन्डाजिम 50 WP (2 ग्राम प्रति लीटर पानी) का घोल डालें।", "नालियों में खड़े पानी को खत्म करने के लिए खेत में जल निकासी सुनिश्चित करें।"], "kn": ["ರೋಗ ಹರಡುವುದನ್ನು ತಡೆಯಲು ಸೋಂಕಿತ ಕಬ್ಬಿನ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ಸುರಕ್ಷಿತವಾಗಿ ಸುಟ್ಟುಹಾಕಿ.", "ಸುತ್ತಮುತ್ತಲಿನ ಮಣ್ಣಿಗೆ ಕಾರ್ಬೆಂಡಾಜಿಮ್ 50 WP (೨ ಗ್ರಾಂ/ಲೀಟರ್ ನೀರು) ಸುರಿಯಿರಿ.", "ಹೊಲದಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಚರಂಡಿ ವ್ಯವಸ್ಥೆ ಮಾಡಿ."], "te": ["వ్యాప్తిని నిరోధించడానికి సోకిన చెరకు పిలకలను పీకి సురక్షితంగా కాల్చివేయండి.", "చుట్టుపక్కల నేలను కార్బండజిమ్ 50 WP (2 గ్రా లీటరు నీటికి) తో తడపండి.", "కాలువలలో నీరు నిల్వ ఉండకుండా పొలంలో నీటి నిష్క్రాసన నిర్ధారించుకోండి."], "ta": ["பூஞ்சை பரவுவதைத் தடுக்க பாதிக்கப்பட்ட கரும்புப் பயிர்களை பிடுங்கி எரிக்கவும்.", "சுற்றியுள்ள மண்ணில் கார்பண்டசிம் 50 WP (2 கிராம்/லி) ஊற்றவும்.", "நீர் தேங்குவதைத் தவிர்க்க வயல் வடிகால் வசதியை உறுதி செய்யவும்."], "ml": ["രോഗം പടരുന്നത് തടയാൻ രോഗബാധിത തണ്ടുകൾ നശിപ്പിക്കുക.", "മണ്ണിൽ കാർബൻഡാസിം തളിക്കുക.", "പാടത്തു വെള്ളക്കെട്ട് ഒഴിവാക്കുക."], "mr": ["संसर्ग पसरू नये म्हणून बाधित ऊसाचे थवे उपटून सुरक्षितपणे जाळून टाका.", "सभोवतालच्या मातीत कार्बेन्डाझिम 50 WP (२ ग्रॅम प्रति लिटर पाणी) ओता.", "पाणी साचू नये म्हणून शेतात पाण्याचा निचरा व्यवस्थित करा."], "gu": ["રોગનો ફેલાવો અટકાવવા ચેપગ્રસ્ત શેરડીના છોડને ઉખાડીને બાળી નાખો.", "આસપાસની જમીનમાં કાર્બેન્ડાઝિમ 50 WP (2 ગ્રામ પ્રતિ લીટર પાણી) રેડો.", "પાણી ભરાઈ ન રહે તે માટે ખેતરમાં સારા નિકાલની વ્યવસ્થા કરો."]}, "default": {"en": ["Inspect surrounding crops for similar disease or pest symptoms.", "Follow recommended crop management and proper drainage practices.", "Consult your local agricultural extension officer for specific dosage."], "hi": ["समान बीमारी या कीट के लक्षणों के लिए आसपास की फसलों का निरीक्षण करें।", "अनुशंसित फसल प्रबंधन और उचित जल निकासी प्रथाओं का पालन करें।", "विशिष्ट खुराक के लिए अपने स्थानीय कृषि विस्तार अधिकारी से परामर्श करें।"], "kn": ["ಇದೇ ರೀತಿಯ ರೋಗ ಅಥವಾ ಕೀಟಗಳ ಲಕ್ಷಣಗಳಿಗಾಗಿ ಸುತ್ತಮುತ್ತಲಿನ ಬೆಳೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ.", "ಶಿಫಾರಸು ಮಾಡಿದ ಬೆಳೆ ನಿರ್ವಹಣೆ ಮತ್ತು ಸರಿಯಾದ ನೀರಾವರಿ ಪದ್ಧತಿ ಅನುಸರಿಸಿ.", "ನಿಖರ ಔಷಧದ ಪ್ರಮಾಣಕ್ಕಾಗಿ ನಿಮ್ಮ ಸ್ಥಳೀಯ ಕೃಷಿ ಅಧಿಕಾರಿಯನ್ನು ಸಂಪರ್ಕಿಸಿ."], "te": ["ఇలాంటి తెగులు లేదా కీటకాల లక్షణాల కోసం చుట్టుపక్కల పంటలను తనిఖీ చేయండి.", "సిఫార్సు చేసిన పంట యాజమాన్యం మరియు నీటి నిష్క్రాసన పద్ధతులను పాటించండి.", "ఖచ్చితమైన మోతాదు కోసం మీ స్థానిక వ్యవసాయ అధికారిని సంప్రదించండి."], "ta": ["இதேபோன்ற நோய் அல்லது பூச்சி அறிகுறிகளுக்கு சுற்றியுள்ள பயிர்களை சோதிக்கவும்.", "பரிந்துரைக்கப்பட்ட பயிர் மேலாண்மை மற்றும் நீர் வடிகால் முறைகளைப் பின்பற்றவும்.", "குறிப்பிட்ட மருந்தின் அளவிற்கு உங்கள் உள்ளூர் வேளாண் அதிகாரியை அணுகவும்."], "ml": ["സമാനമായ രോഗലക്ഷണങ്ങൾക്കായി ചുറ്റുമുള്ള വിളകൾ പരിശോധിക്കുക.", "ശുപാർശ ചെയ്യുന്ന വിള പരിപാലന രീതികൾ പാലിക്കുക.", "വിശദവിവരങ്ങൾക്ക് കൃഷി ഓഫീസറെ ബന്ധപ്പെടുക."], "mr": ["तशाच प्रकारच्या रोगासाठी किंवा किडीसाठी सभोवतालच्या पिकांची पाहणी करा.", "शिफारस केलेल्या पीक व्यवस्थापन व योग्य निचरा पद्धतींचा अवलंब करा.", "औषधाच्या योग्य प्रमाणासाठी स्थानिक कृषी अधिकाऱ्याचा सल्ला घ्या."], "gu": ["સમાન રોગ અથવા જીવાતના લક્ષણો માટે આસપાસના પાકની તપાસ કરો.", "ભલામણ કરેલ પાક વ્યવસ્થાપન અને સારા નિકાલ પદ્ધતિઓનું પાલન કરો.", "ચોક્કસ માત્રા માટે તમારા સ્થાનિક ખેતીવાડી અધિકારીની સલાહ લો."]}};

export function getLocalizedDiseaseName(diseaseName: string, language: string): string {
  if (!diseaseName) return "";
  const lang = (language || "en").toLowerCase();
  const dict = DISEASE_NAMES_LOCALE[diseaseName];
  if (dict && dict[lang]) {
    return dict[lang];
  }
  return diseaseName;
}

export function getLocalizedDiseaseDetails(
  diseaseName: string,
  language: string,
  fallbackDetails: DiseaseDetails
): DiseaseDetails {
  const lang = (language || "en").toLowerCase();
  const dict = DISEASE_DETAILS_LOCALE[diseaseName] || DISEASE_DETAILS_LOCALE["default"];

  if (!dict) return fallbackDetails;

  return {
    symptoms: dict.symptoms?.[lang] || dict.symptoms?.["en"] || fallbackDetails.symptoms,
    causes: dict.causes?.[lang] || dict.causes?.["en"] || fallbackDetails.causes,
    treatment: dict.treatment?.[lang] || dict.treatment?.["en"] || fallbackDetails.treatment,
    prevention: dict.prevention?.[lang] || dict.prevention?.["en"] || fallbackDetails.prevention,
    precautions: dict.precautions?.[lang] || dict.precautions?.["en"] || fallbackDetails.precautions,
  };
}

export function getLocalizedRecommendedActions(
  diseaseName: string,
  language: string,
  fallbackActions: string[]
): string[] {
  const lang = (language || "en").toLowerCase();
  const dict = RECOMMENDED_ACTIONS_LOCALE[diseaseName] || RECOMMENDED_ACTIONS_LOCALE["default"];

  if (dict && dict[lang]) {
    return dict[lang];
  }
  if (dict && dict["en"]) {
    return dict["en"];
  }
  return fallbackActions;
}
